revision.text:
== Zählungen ==

=== Anzahl Fälle ===
{{#cargo_query:
  tables=Fälle|fields=COUNT(*)=Anzahl_Fälle|format=inline}}

=== Anzahl Beschuldigte ===
{{#cargo_query:
  tables=Beschuldigte|fields=COUNT(*)=Anzahl_Beschuldigte|format=inline}}

=== Anzahl Betroffene ===
{{#cargo_query:
  tables=Betroffene|fields=COUNT(*)=Anzahl_Betroffene|format=inline}}

== Quellenkritik-Score ==
{{#cargo_query:
 tables=Fälle|fields=Quellenkritik, COUNT(*)=Anzahl|group by=Quellenkritik|format=table|headers=Score, Anzahl}}

== Art des Kontakts ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Physischer_Kontakt, COUNT(*)=Anzahl|group by=Physischer_Kontakt|format=table|headers=Kontakt, Anzahl}}

== Kein physischer Kontakt ==
{{#cargo_query:
  tables=Fälle|fields=Art_des_Missbrauch, COUNT(*)=Anzahl|where=Physischer_Kontakt="kein physischer Kontakt"|group by=Art_des_Missbrauch|order by=Anzahl DESC|format=table|headers=Art des Missbrauchs, Anzahl}}

== Art des physischen Missbrauchs (Kombinationen) ==
{{#cargo_query:
 tables=Fälle|fields=Art_des_Missbrauch__full=Kombi, COUNT(*)=Anzahl|where=Physischer_Kontakt="physischer Kontakt"|group by=Kombi|format=table|headers=Art des Missbrauchs (Kombinationen), Anzahl}}

== Art des physischen Kontakts einzeln ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Art_des_Missbrauch, COUNT(*)=Anzahl|where=Physischer_Kontakt="physischer Kontakt"|group by=Art_des_Missbrauch|format=table|headers=Art des Missbrauchs (Mehrfachnennung möglich), Anzahl}}

== Weihegrade Beschuldigte ==
{{#cargo_query:
 tables=Beschuldigte|fields=Weihegrad, COUNT(*)=Anzahl|group by=Weihegrad|format=table|headers=Weihegrad, Anzahl}}

== Funktion Beschuldigte je Fall ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Funktion, COUNT(*)=Anzahl|group by=Funktion|format=table|headers=Funktion Täter im jeweiligen Fall, Anzahl}}

== Geschlecht Betroffene ==
{{#cargo_query:
 tables=Betroffene|fields=Geschlecht, COUNT(*)=Anzahl|group by=Geschlecht|format=table|headers=Geschlecht, Anzahl}}

== Geschlecht Beschuldigte ==
{{#cargo_query:
 tables=Beschuldigte|fields=Geschlecht, COUNT(*)=Anzahl|group by=Geschlecht|format=table|headers=Geschlecht, Anzahl}}

== Nationalität Beschuldigte ==
{{#cargo_query:
 tables=Beschuldigte|fields=Nationalität, COUNT(*)=Anzahl|group by=Nationalität|format=table|headers=Nationalität, Anzahl}}

== Jahrgang Beschuldigte ==
{{#cargo_query:
  tables=Beschuldigte|fields=CONCAT((YEAR(Geburtsdatum) DIV 10) * 10, "er")=Jahrzehnt, COUNT(*)=Anzahl|group by=(YEAR(Geburtsdatum) DIV 10) * 10|order by=Jahrzehnt|format=table|headers=Jahrzehnt, Anzahl}}

