== Geburtsdatum Beschuldigte unbekannt ==
{{#cargo_query:
  tables=Beschuldigte|fields=COUNT(*)=Anzahl|where=Geburtsdatum IS NULL OR Geburtsdatum=""|format=table|headers=Unbekanntes Geburtsdatum}}

== Tatkontext weibliche Beschuldigte ==
{{#cargo_query:
  tables=Fälle, Beschuldigte|join on=Fälle.Beschuldigter=Beschuldigte._pageName|fields=Fälle._pageName=Fall, , Beschuldigte.Geschlecht, Fälle.Alter_Betroffener_operationalisiert, Fälle.Tatkontext|where=Beschuldigte.Geschlecht="weiblich"|format=table|headers=Fall, Geschlecht Beschuldigte, Alter Betroffene, Tatkontext}}

== Alter Betroffene zum Zeitpunkt der Tat / zu Beginn der Tatdauer ==
{{#cargo_query:
 tables=Fälle|fields=Alter_Betroffener_operationalisiert, COUNT(*)=Anzahl|group by=Alter_Betroffener_operationalisiert|format=table|headers=Alter Betroffene_operationalisiert, Anzahl}}

== Kanton des Falls ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Kanton, COUNT(*)=Anzahl|group by=Kanton|format=table|headers=Kanton, Anzahl}}

== Genugtuungsfonds ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Genugtuungskommission_behandelt, COUNT(*)=Anzahl|group by=Genugtuungskommission_behandelt|format=table|headers=Genugtuungsfonds, Anzahl}}

== Fachgremien ==
{{#cargo_query:
  tables=Fälle|fields=Fachgremien, COUNT(*)=Anzahl|group by=Fachgremien|order by=Anzahl DESC|format=table|headers=Fachgremien, Anzahl behandelter Fälle}}

== Strafverfolgung ==
{{#cargo_query:
  tables=Fälle|fields=Strafverfolgungsbehörden_informiert, COUNT(*)=Anzahl|group by=Strafverfolgungsbehörden_informiert|order by=Anzahl DESC|format=table|headers=Strafverfolgung informiert?, Anzahl}}

== Zeitpunkt Zeitraum der Tat ==
{{#cargo_query:
 tables=Fälle|fields=Fälle.Tatzeitpunkt_Tatzeitraum, COUNT(*)=Anzahl|group by=Tatzeitpunkt_Tatzeitraum|format=line chart|headers=Tatzeitpunkt/Tatzeitraum, Anzahl|limit=1000}}

== Troubleshooting ==

=== Ohne Geschlechtsangabe ===
{{#cargo_query:
  tables=Beschuldigte|fields=Beschuldigte._pageName=Beschuldigter|where=Geschlecht IS NULL OR Geschlecht=""|format=table|headers=Beschuldigter|link=all}}{{#cargo_query:
  tables=Betroffene|fields=Betroffene._pageName=Betroffene|where=Geschlecht IS NULL OR Geschlecht=""|format=table|headers=Betroffene|link=all}}

=== Ordensbruder/Ordensschwester mit Weihe ===
{{#cargo_query:
  tables=Beschuldigte|fields=Beschuldigte._pageName=Beschuldigter, Funktion, Weihegrad|where=Funktion HOLDS "Ordensbruder/Ordensschwester" AND Weihegrad="Ordenspriester"|format=table|headers=Beschuldigter, Funktion, Weihegrad|link=all}}

== Troubleshooting 2 ==

=== Fälle ohne Angabe zu "physisch oder "nicht physisch" in den Bistümern St.Gallen und Chur ===
{{#cargo_query:
  tables=Fälle|fields=Fälle._pageName=Fall, Institutioneller_Kontext, Physischer_Kontakt|where=(Physischer_Kontakt IS NULL OR Physischer_Kontakt="")
    AND (Institutioneller_Kontext HOLDS "Bistum St.Gallen"
         OR Institutioneller_Kontext HOLDS "Bistum Chur")|format=table|headers=Fall, Institutioneller Kontext, Physischer Kontakt|link=all}}

=== Beschuldigte ohne Geburtsdatum Bistum Basel ===
{{#cargo_query:
  tables=Beschuldigte|fields=Beschuldigte._pageName=Beschuldigter, Institutioneller_Kontext, Geburtsdatum|where=(Geburtsdatum IS NULL OR Geburtsdatum="")
    AND (Institutioneller_Kontext HOLDS "Bistum Basel"
         OR Institutioneller_Kontext HOLDS "Basel")|format=table|headers=Beschuldigter, Institutioneller Kontext, Geburtsdatum|link=all}}

=== Altersangaben Betroffene mit falschem Format ===
{{#cargo_query:
  tables=Fälle|fields=Fälle._pageName=Fall, Alter_Betroffener|where=Alter_Betroffener LIKE "%-%"|format=table|headers=Fall, Alter Betroffener|link=all}}

== Fälle mit FachgremiumFehlt ==
{{#cargo_query:
  tables=Fälle|fields=Fälle._pageName=Fall, Fachgremien, Institutioneller_Kontext|where=Fachgremien HOLDS "FachgremiumFehlt"|format=table|headers=Fall, Fachgremien, Institutioneller Kontext|link=all}}

== Fälle ohne Quellenkritik-Score ==
{{#cargo_query:
  tables=Fälle|fields=Fälle._pageName=Fall, Institutioneller_Kontext|where=Quellenkritik IS NULL OR Quellenkritik=""|format=table|headers=Fall, Institutioneller Kontext|link=all}}

== Fälle Basel ohne Ägide ==
{{#cargo_query:
  tables=Fälle|fields=Fälle._pageName=Fall, Institutioneller_Kontext, Fälle.Ägide|where=(Institutioneller_Kontext HOLDS "Bistum Basel") 
    AND (Fälle.Ägide IS NULL OR Fälle.Ägide="")|format=table|headers=Fall, Institutioneller Kontext, Agide|link=all}}
